def transform(grid):
    g=[row[:] for row in grid]
    n=len(grid); h=n//2
    regions=[(0,h,0,h),(0,h,h+1,n),(h+1,n,0,h),(h+1,n,h+1,n)]
    red=components(g,2,regions[0])[0]
    sr0=min(r for r,c in red); sr1=max(r for r,c in red)+1
    sc0=min(c for r,c in red); sc1=max(c for r,c in red)+1
    source_colors=sorted({g[r][c] for r in range(h) for c in range(h) if g[r][c]!=4})
    rects=[]
    for color in source_colors:
      for comp in components(g,color,regions[0]):
       rects.append((color,min(r for r,c in comp),max(r for r,c in comp)+1,min(c for r,c in comp),max(c for r,c in comp)+1))
    for qi,reg in enumerate(regions[1:],1):
      tr=components(g,2,reg)[0]
      tr0=min(r for r,c in tr); tr1=max(r for r,c in tr)+1
      tc0=min(c for r,c in tr); tc1=max(c for r,c in tr)+1
      s=(tr1-tr0)/(sr1-sr0)
      flip_r=qi>=2; flip_c=qi in (1,3)
      for color,r0,r1,c0,c1 in rects:
       if flip_r:
        nr0=round(tr1-(r1-sr0)*s); nr1=round(tr1-(r0-sr0)*s)
       else:
        nr0=round(tr0+(r0-sr0)*s); nr1=round(tr0+(r1-sr0)*s)
       if flip_c:
        nc0=round(tc1-(c1-sc0)*s); nc1=round(tc1-(c0-sc0)*s)
       else:
        nc0=round(tc0+(c0-sc0)*s); nc1=round(tc0+(c1-sc0)*s)
       for r in range(nr0,nr1):
        for c in range(nc0,nc1): g[r][c]=color
    return g
